parts.text:
root = Stack([pageHeader, planSteps, cfgHeader, cfgForm, taskHeader, taskTable, taskHint, nextBtns], "column", "l")
pageHeader = CardHeader("第三步：两周试用计划", "团队版 · 星河设计 · 按三阶段推进")
planSteps = Steps([step1, step2, step3])
step1 = StepsItem("准备（第1–2天）", "建立1个试点项目，整理5个活跃项目中最典型的任务导入；邀请3名成员，并添加1–2位只读客户访客，确认客户能看到进度但无法编辑。")
step2 = Step第Item: 1
step2 = StepsItem("第一周", "所有新任务统一在看板流转：建卡、指派负责人、设截止时间；团队成员每天更新状态，期间不做额外的线下任务表格，保持单一信息源。")
step3 = StepsItem("第二周", "延续使用习惯，观察客户查看情况是否减少了反复沟通；周末进行首次数据复盘，对照完成率、逾期和交接时长。")
cfgHeader = InlineHeader("试用参数", "选择开始日期并设定目标")
cfgForm = Form("试用参数", cfgButtons, [fDate, fGoal])
fDate = FormControl("期望开始日期", DatePicker("期望开始日期", "single", { required: true }), "建议尽早，保持两周完整周期")
fGoal = FormControl("完成率目标", Slider("完成率目标", "discrete", 50, 100, 5, [80], "默认80%，可拖动调整"))
cfgButtons = Buttons([Button("保存试用参数", Action([@ToAssistant("我已确认试用开始日期与完成率目标")]), "primary")])
taskHeader = InlineHeader("3个试点任务", "可直接点击单元格修改任务和负责人")
taskTable = EditableTable("试点任务", [cTask, cOwner, cStatus], [r1, r2, r3])
cTask = { type: "text", key: "task", header: "任务", width: 40 }
cOwner = { type: "select", key: "owner", header: "负责人", options: [o1, o2, o3] }
o1 = { value: "小林", label: "小林" }
o2 = { value: "小周", label: "小周" }
o3 = { value: "小陈", label: "小陈" }
cStatus = { type: "select", key: "status", header: "状态", options: [s1, s2, s3] }
s1 = { value: "todo", label: "待开始" }
s2 = { value: "doing", label: "进行中" }
s3 = { value: "done", label: "已完成" }
r1 = { id: "1", values: ["建立试点项目并导入典型任务", "小林", "todo"] }
r2 = { id: "2", values: ["邀请3名成员与只读客户访客", "小周", "todo"] }
r3 = { id: "3", values: ["每周五复盘：进度、逾期与交接时长", "小陈", "todo"] }
taskHint = TextContent("以上只是试用计划，尚未创建任何真实项目；表格内容确认后随下一步一起生效。")
nextBtns = Buttons([Button("查看试用数据", Action([@ToAssistant("查看内置试用样本的效果数据")]), "primary")])
